architecture.h4_f:
msg = CBOR{v:1, text, reply_to, send_at}
ct = AES-GCM-256-Šifrēt(k, nonce, msg, aad=room_id)
POST /api/rooms/{id}/messages {šifrēts teksts: hex(ct), nonce: hex}

cryptoWire.h1_f:
pt = CBOR{v:1, teksts, atbilde_uz?, pavediena_id?, pieminējumi?, nosūtīts_at}
ct = AES-GCM-256-Šifrēt(telpas_atslēga, nonce, pt, aad=hex(telpas_id))
vads = CBOR{
  v: 1,
  šifrētais teksts: hex(ct), // mainīgs garums
  nonce: hex (12 B),
  sender_pseudo: hex (16 B),
  send_at: unix_ms
}

cryptoWire.h5_f:
ārējais = CBOR{
  avota_node: hex32,
  mērķa_lietotājs: int64,
  inner_ciphertext: baiti,
  inner_nonce: baiti,
  send_at: unix_ms
}
sig = Ed25519-Sign(avots_priv, ārējais)
POST /federation/deliver { aploksne: ārējā, sig: hex64}

auth.h1_f:
POST /api/autentifikācija/reģistrs
  { lietotājvārds, parole, x25519_public_key, display_name, phone?, email?, avatar_emoji }

201. atbilde izveidota:
  { access_token, refresh_token, user_id, username, ... }

auth.h3_f:
access_token lietderīgā slodze:
  { sub: user_id, jti: device_id, tips: "piekļuve", exp: tagad + 15 min }
refresh_token slodze:
  { sub: user_id, jti: device_id, typ: "refresh", exp: now + 30d }

HS256 parakstīts ar mezgla 64 baitu noslēpumu no .env

auth.h4_f:
register_begin(): izaicinājums = rand(32)
                    opcijas = { rp.id, user.id, pubKeyCredParams, izaicinājums }
                    atgriešanas iespējas

register_finish(attestāts):
  pārbaudīt apliecinājumu pret TPM / drošā anklāva sakne CA
  veikals { akreditācijas_id, publiskā_atslēga, skaitītājs: 0}

auth.h7_f:
POST /api/autentifikācija/qr/begin
  → { nonce: 128-bit hex, ttl: 60 }
QR slodze = { nonce, user_id, server: "https://node.example"}

POST /api/authentication/qr/verify {nonce}
  → reģistrēta jauna ierīce; JWT atgriezās.

rooms.h6_f:
sender_pseudo = HMAC-SHA256(telpas_pseudo_sāls, sūtītāja_id)[:16] // 32 hex
šifrētais teksts = AES-GCM-Šifrēt(telpas_atslēga, nonce, CBOR_payload, aad=telpas_id)

Fan-out rāmis: {type:"m", telpa, ziņa:{id, ct, nonce, sender_pseudo, send_at} }

files.h2_f:
init POST /api/files/resumable/init {faila nosaukums, izmērs, chunk_size_hint}
            ← {upload_id, chunk_size}
chunk PUT /api/files/resumable/{upload_id}/chunk/{offset} <ct bytes>
            ← 204
finalize POST /api/files/resumable/{upload_id}/finalise {plain_blake3}
            ← 201 {file_id, url}
TTL nepabeigtā: 24 h

presence.h1_f:
klients: pirmajā taustiņu nospiešanas reizē → nosūtīt {type:"t", status:"start"}
         vairs nesūta 3 s, ja vien stāvoklis nemainās
         10 s pēc pēdējā taustiņa nospiešanas → sūtīt {type:"t", status:"stop"}
uztvērējs: automātiska apstāšanās 10 s pēc pēdējā "start", ja nav pienākusi "stop".

calls.h1_f:
POST /api/calls/{room_id}/start {video, audio} → call_id
WS apraide {type:"c", veida:"invite", call_id}
WS apraide {tips:"c", veids:"piedāvājums", sdp}
WS apraide {tips:"c", veids:"atbilde", sdp}
WS apraide {tips:"c", veids:"kandidāts",ledus} × N
POST /api/calls/{call_id}/end

federation.h2_f:
aploksne = {
  avota_mezgls: hex32,
  mērķa_lietotājs: int64,
  inner_ciphertext: baiti,
  inner_nonce: baiti,
  send_at : unix_ms,
}
sig = Ed25519Sign(avota_privāts, CBOR(aploksne))
POST /federācija/piegādāt { aploksne, paraksts }

gossip.h3_f:
reklāma = {pubkey, endpoint, reklamēts_at}
sig = Ed25519-Sign(pubkey_priv, CBOR(reklāma))
tenku slodze: [..., {ad, sig}, ...]

uztvērējs: pārbaudiet sig pret ad.pubkey → store iff ok
papildu: PoW no 2^18 sākuma nullēm vietnē {pubkey, endpoint}

stealth.h2_f:
ClientHello baiti = chrome_120_template ar {
  nejaušība = mūsu nejaušība,
  servera_nosaukums = mūsu resursdatora nosaukums (vai ECH apzīmēts),
  session_id = mūsu sesijas ID,
}
JA4 = t13d_xxxx_xxxx_xxxx (atbilst pašreizējam Chrome stabilajam)

stealth.h4_f:
DoH: POST https://cloudflare-dns.com/dns-query {name: x.vortexx.sol}
ECH: ClientHello.extensions += encrypted_sni(publiskā_atslēga_no_HTTPS_ieraksts)
DGA: domēns(t) = bāze32( SHA256(sēkla ∥ YYYY-MM-DD) )[:16] + ".example"

push.h4_f:
iOS NSE: didReceive(request) { atšifrēt(request.content.userInfo)}
Android FCM: onMessageReceived(remoteMessage) { atšifrēt(remoteMessage.data)}
Tīmeklis SW: self.addEventListener('push', e => atšifrēt(e.data))

controller.h2_f:
rīks = sign_tool
ievade = avota koks, atslēgas/release.key
manifests = {
  versija: "0.1.0",
  built_at: unix_ms,
  faili: [{ceļš, sha256, izmērs}, ...]
}
sig = Ed25519-Sign(release_priv, CBOR(manifests))
izvade = INTEGRITY.sig.json = {manifests, parakstījis: pub_hex, sig: sig_hex}

bots.h1_f:
izveidot: POST /api/bots {lietotājvārds, parādāmais_nosaukums, kods}
          → {bot_id, marķieris, pubkey}
palaist: procesā (korutīna mezglā)
      OR ārēja (long-poll /api/bots/{id}/updates, token-auth'd)
ziņojums: {teksts, paraksts: Ed25519-Sign(bot_priv, canonical_msg)}

bots.h2_f:
uz /sākt {
  izdod "Laipni lūdzam, {ctx.first_name}"
}
uz /pievienot <preci> {
  state.list = (state.list vai []) + [ctx.args.item]
  emitēt "Pievienots: {ctx.args.item}"
}

security.h4_f:
canary.txt (katru dienu):
  {date, sig: Ed25519-Sign(release_priv, date)}
klients pārbauda → nav vai ir nederīgs ⇒ ir aizdomas, ka ir apdraudēts

ārkārtas situācija:
  admin POST /api/admin/revoke-all {reason}
  mezglu pārraides {tips:"n", notikums:"kompromiss", iemesls}
  klienti noslauka atslēgas, piespiež atkārtoti palaist

debugging.h2_f:
likmju histogrammas (par maršrutu + metodi):
  vortex_http_requests_total{route,method,status}
  vortex_http_request_duration_seconds_bucket{route,method,le}

tīmekļa kontaktligzdas mērītāji:
  vortex_ws_connections{node}
  vortex_ws_fanout_queue_depth{telpa,lietotājs}

pielāgoti skaitītāji:
  vortex_messages_sent_total{room_type}
  vortex_calls_started_total{kind}

login.h3_f:
{
  "lietotājvārds": "alise",
  "password": "pareiza zirga akumulatora skavas skava",
  "totp": "123456" // nepieciešams, ja ir iespējots 2FA
}

login.h4_f:
par panākumiem: 201 + JWT aploksne (tāda pati forma kā reģistram)
uz 2FA nepieciešams: 200 { "needs_2fa": true } (vēl nav JWT)
kļūdas gadījumā: 401 { "kļūda":"nederīgi_akreditācijas dati"}

apns.h1_f:
POST https://api.push.apple.com/3/device/<device_token>
Galvenes: apns-topic: <bundle_id>, apns-push-type: alert, apns-collapse-id: room:42
Pamatteksts: {aps: {alert: {title, body}}, dati: <sealed>}

bmp.h1_f:
pastkastes_id = HKDF(adresāta_pubkey, info="bmp-v1", len=32)
Depozīts: POST /bmp/deposit {mailbox_id, blob ≤1 MB}
Saņemšana: GET /bmp/messages (auth'd)

controller.h1_f:
GET /v1/integrity → {statuss, signed_by, matched, mismatched, …}
GET /v1/health → {statuss, version, pubkey, stats}
GET /v1/entries → [{protocol, url}, …]
GET /v1/spoguļi → [kontrollera_url, …]

fcm.h1_f:
POST https://fcm.googleapis.com/v1/projects/<project>/messages:send
Autorizācija: nesējs <oauth2_token>
Pamatteksts: {ziņojums: {token: <ierīce>, dati: {...sealed...}, Android: {collapse_key}}}

federation.h1_f:
aploksne = {avota_mezgls, mērķa_lietotājs, iekšējais_ct, inner_nonce, send_at}
sig = Ed25519-Sign(avota_privāts, CBOR(aploksne))
POST /federācija/piegādāt {aploksne, zīme}
B pārbauda: sig pret federations[source_node].pubkey

fts5.h1_f:
CREATE VIRTUAL TABLE messages_fts USING fts5(
  saturs, -- tokenizēta kolonna
  room_id UNINDEXED,
  tokenize = 'unicode61 remove_diacritics 2'
);
vaicājums: SELECT rowid FROM messages_fts WHERE saturs MATCH 'foo'

gravitix.h1_f:
on /start { emit "Laipni lūdzam, {ctx.first_name}" }
uz /pievienot <preci> {
  state.list = (state.list vai []) + [ctx.args.item]
  emitēt "Pievienots: {ctx.args.item}"
}

prekey.h1_f:
komplekts = {
  identitātes_pk,
  signed_prekey_pk,
  signed_prekey_sig = Ed25519-Sign(identity_priv, signed_prekey_pk),
  one_time_prekeys: [pk_0, pk_1, ..., pk_9]
}

vapid.h1_f:
VAPID atslēgas: Ed25519 atslēgpāris katram mezglam
zīme JWT: {aud: push_service_origin, exp: now + 12h, sub: mailto:ops@example}
push pieprasījuma galvenes: Autorizācija: vapid t=<jwt>, k=<vapid_public_key>
